import{_ as n,a0 as o,w as l,s as r,ao as d,I as p,x as t,a1 as i,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const m=JSON.parse('{"title":"如何为 APT 命令设置代理 | LCTT x X-CMD","titleTemplate":false,"description":"如何为 APT 命令设置代理 | LCTT (202305) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何为 APT 命令设置代理 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何为 APT 命令设置代理 | LCTT (202305) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202305/20230422.0 ⭐️ How to Set Proxy Settings for APT Command","title":"如何为 APT 命令设置代理","tag":"202305","desc":""},"relativePath":"202305/20230422.0 ⭐️ How to Set Proxy Settings for APT Command.md","filePath":"[post].md"}'),h={name:"202305/20230422.0 ⭐️ How to Set Proxy Settings for APT Command.md"};function c(g,s,u,k,b,f){const a=o("Link");return l(),r("div",null,[s[15]||(s[15]=d(`<h1 id="如何为-apt-命令设置代理" tabindex="-1">如何为 APT 命令设置代理 <a class="header-anchor" href="#如何为-apt-命令设置代理" aria-label="Permalink to “如何为 APT 命令设置代理”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202305/15/184447hh8ac86hkycy6jio.jpg" alt=""></p><blockquote><p>在本指南中，你将了解如何在 Ubuntu/Debian Linux 发行版中为 <code>apt</code> 命令设置代理。</p></blockquote><p>代理服务器是位于请求资源的客户端系统或最终用户与资源本身之间的中间服务器。在大多数情况下，代理服务器充当最终用户和互联网之间的网关。</p><p>对于组织和企业环境，代理服务器提供了许多好处。它通过阻止被认为会影响员工工作效率的网站来控制互联网的使用。它还通过数据加密增强隐私并提高组织的安全性。</p><p>有几种方法可以为 <code>apt</code> 命令设置代理，让我们直接进入。</p><p>注意：为了演示，我们将使用 Ubuntu 22.04。</p><h3 id="使用代理文件为-apt-配置代理" tabindex="-1">使用代理文件为 APT 配置代理 <a class="header-anchor" href="#使用代理文件为-apt-配置代理" aria-label="Permalink to “使用代理文件为 APT 配置代理”">​</a></h3><p>为 <code>apt</code> 命令配置代理的最简单方法是创建一个 <code>proxy.conf</code> 文件，如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vi /etc/apt/apt.conf.d/proxy.conf</span></span></code></pre></div><p>对于没有用户名和密码的代理服务器，添加以下条目，如下：</p><p>对于 HTTP 代理，添加以下条目：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Acquire::http::Proxy &quot;http://proxy-IP-address:proxyport/&quot;;</span></span></code></pre></div><p>对 HTTPS 代理执行相同的操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Acquire::https::Proxy &quot;http://proxy-IP-address:proxyport/&quot;;</span></span></code></pre></div><p>例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat  /etc/apt/apt.conf.d/proxy.conf</span></span>
<span class="line"><span>Acquire::http::Proxy &quot;http://192.168.56.102:3128/&quot;;</span></span>
<span class="line"><span>Acquire::https::Proxy &quot;http://192.168.56.102:3128/&quot;;</span></span></code></pre></div><p>如果你的代理服务器需要用户名和密码详细信息，请按以下方式添加：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Acquire::http::Proxy &quot;http://username:password@proxy-IP-address:proxyport&quot;;</span></span>
<span class="line"><span>Acquire::https::Proxy &quot;http://username:password@proxy-IP-address:proxyport&quot;;</span></span></code></pre></div><p>例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat  /etc/apt/apt.conf.d/proxy.conf</span></span>
<span class="line"><span>Acquire::http::Proxy &quot;http://init@PassW0rd321#@192.168.56.102:3128/&quot;;</span></span>
<span class="line"><span>Acquire::https::Proxy &quot;http://init@PassW0rd321#@192.168.56.102:3128/&quot;;</span></span></code></pre></div><p>完成后，保存更改并退出配置文件。代理设置将在你下次运行 APT 包管理器时生效。</p><p>例如，你可以更新本地包索引，然后安装 <code>net-tools</code> 包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt update</span></span>
<span class="line"><span>$ sudo apt install net-tools -y</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/Apt-Install-Package-Proxy-Settings-1024x403.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>验证代理服务器日志以确认 <code>apt</code> 命令正在使用代理服务器下载包。在代理服务器运行时：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># tail -f /var/log/squid/access.log  | grep -i 192.168.56.240</span></span></code></pre></div><p>这里 <code>192.168.56.240</code> 是我们 Ubuntu 机器的 IP 地址。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/Grep-Proxy-Logs-Ubuntu-Machine-1024x326.png?ezimgfmt=ng:webp/ngcb22" alt=""></p><p>完美，上面的输出确认我们的 Ubuntu 系统的 <code>apt</code> 命令正在通过代理服务器（192.168.56.102）下载包。</p><h3 id="另一种指定代理详细信息的方法" tabindex="-1">另一种指定代理详细信息的方法 <a class="header-anchor" href="#另一种指定代理详细信息的方法" aria-label="Permalink to “另一种指定代理详细信息的方法”">​</a></h3><p>除了第一种方法，你还可以用更简单的方式指定代理详细信息。再次创建一个 <code>proxy.conf</code> 文件，如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vi /etc/apt/apt.conf.d/proxy.conf</span></span></code></pre></div><p>对于没有用户名和密码的代理服务器，如图所示进行定义。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Acquire {</span></span>
<span class="line"><span>  http::Proxy &quot;http://proxy-IP-address:proxyport/&quot;;</span></span>
<span class="line"><span>  https::Proxy &quot;http://proxy-IP-address:proxyport/&quot;;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>示例文件如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vi /etc/apt/apt.conf.d/proxy.conf</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/04/Proxy-conf-Apt-Command-Ubuntu.png" alt=""></p><p>对于具有用户名和登录详细信息的代理服务器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Acquire {</span></span>
<span class="line"><span>   http::Proxy &quot;http://username:password@proxy-IP-address:proxyport/&quot;;</span></span>
<span class="line"><span>   https::Proxy &quot;http://username:password@proxy-IP-address:proxyport/&quot;;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>保存更改并退出配置文件。提醒一下，当你开始使用 APT 包管理器，这些设置就会立即生效。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>本指南到此结束。在本教程中，我们演示了如何为 Debian/Ubuntu Linux 发行版中使用的 APT 包管理器配置代理设置。本文就到这里了。</p><p>（题图：MJ/dfb4d5a0-9150-47bd-9f54-c120ddd77046）</p><hr>`,45)),p("p",null,[s[1]||(s[1]=t("via: ",-1)),i(a,{href:"https://www.linuxtechi.com/set-proxy-settings-for-apt-command/"},{default:e(()=>[...s[0]||(s[0]=[t("https://www.linuxtechi.com/set-proxy-settings-for-apt-command/",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=t("作者：",-1)),i(a,{href:"https://www.linuxtechi.com/author/james/"},{default:e(()=>[...s[2]||(s[2]=[t("James Kiarie",-1)])]),_:1}),s[7]||(s[7]=t(" 选题：",-1)),i(a,{href:"https://github.com/lkxed/"},{default:e(()=>[...s[3]||(s[3]=[t("lkxed",-1)])]),_:1}),s[8]||(s[8]=t(" 译者：",-1)),i(a,{href:"https://github.com/geekpi"},{default:e(()=>[...s[4]||(s[4]=[t("geekpi",-1)])]),_:1}),s[9]||(s[9]=t(" 校对：",-1)),i(a,{href:"https://github.com/wxy"},{default:e(()=>[...s[5]||(s[5]=[t("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=t("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[10]||(s[10]=[t("LCTT",-1)])]),_:1}),s[13]||(s[13]=t(" 原创编译，",-1)),i(a,{href:"https://linux.cn/"},{default:e(()=>[...s[11]||(s[11]=[t("Linux中国",-1)])]),_:1}),s[14]||(s[14]=t(" 荣誉推出",-1))])])}const P=n(h,[["render",c]]);export{m as __pageData,P as default};
